    """Band weekly minutes into heavy (60 or more) and light. Missing minutes stay missing."""
    minutes = df["minutes"]
    band = np.where(minutes >= 60, "heavy", "light")
    return df.assign(viewing_band=band)

exercises.fix_solution:
def add_viewing_band(df: pd.DataFrame) -> pd.DataFrame:
    """Band weekly minutes into heavy (60 or more) and light. Missing minutes stay missing."""
    minutes = df["minutes"]
    band = pd.Series(np.where(minutes >= 60, "heavy", "light"), index=df.index)
    return df.assign(viewing_band=band.where(minutes.notna()))
